#!/usr/bin/env node
// scripts/po-outreach-cheatsheet.mjs  (READ-ONLY)
// Builds a human copy-paste cheatsheet from the artifact generated by
// po-fulfillment-orchestrator.mjs (outreach action):
//   data/out/po-outreach-messages.json  (channel + message per supplier)
//   data/out/po-execution-queue.json    (item ids + recipients)
//
// Writes data/out/po-outreach-drafts.md, sorted by supplier value. Operator
// sends/checks via their own phone/app, then records real tracking in
// data/out/waybills.csv.
//
//   node scripts/po-outreach-cheatsheet.mjs

import 'dotenv/config';
import { readFileSync, writeFileSync, existsSync, mkdirSync } from 'fs';
import { resolve, dirname } from 'path';
import { fileURLToPath } from 'url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const ROOT = resolve(__dirname, '..');
const OUT = resolve(ROOT, 'data', 'out');
if (!existsSync(OUT)) mkdirSync(OUT, { recursive: true });

const msgPath = resolve(OUT, 'po-outreach-messages.json');
const queuePath = resolve(OUT, 'po-execution-queue.json');
if (!existsSync(msgPath) || !existsSync(queuePath)) {
  console.error('Missing data/out/po-outreach-messages.json or po-execution-queue.json. Run: node scripts/po-execution-queue.mjs && node scripts/po-fulfillment-orchestrator.mjs');
  process.exit(1);
}

const messages = JSON.parse(readFileSync(msgPath, 'utf8'));
const queue = JSON.parse(readFileSync(queuePath, 'utf8'));

const itemsBySupplier = new Map(
  queue.suppliers.map((s) => [s.name, s.items ?? []]),
);

function itemLines(name) {
  const items = itemsBySupplier.get(name) ?? [];
  const lines = items.slice(0, 10).map((i) => {
    const line = `  - ${i.name} (${i.recipient || '?'}, ${i.status || '?'})`;
    return i.id ? `${line}  ·  itemId=${i.id}` : line;
  });
  if (items.length > 10) lines.push(`  - … and ${items.length - 10} more`);
  return lines.join('\n');
}

function channelBlock(ch) {
  switch (ch.channel) {
    case 'self_service':
      return [
        `Ouvrir/Check: ${ch.platform || 'platform'}`,
        `Tracking: ${ch.howToTrack || 'follow order → copy tracking'}`,
        `Action: ${ch.actionForOperator || 'capture tracking numbers'}`,
      ].join('\n');
    case 'whatsapp':
    case 'phone':
    case 'email':
      return [`Copy-paste (${ch.channel}):`, '', '```', ch.message || '', '```'].join('\n');
    case 'in_person':
      return ch.howToTrack || 'Visit in person for delivery status';
    default:
      return ch.actionForOperator || `Contact supplier for tracking (${ch.pendingCount} items, ${ch.supplierTotal} MAD)`;
  }
}

const entries = Object.entries(messages).sort((a, b) => b[1].supplierTotal - a[1].supplierTotal);

const md = [];
md.push(`# PO Outreach — Copy-Paste Drafts`);
md.push('');
md.push(`> Generated ${new Date().toISOString()} · ${entries.length} suppliers needing action · READ-ONLY.`);
md.push('> Operator sends/checks via their own phone/app. After you obtain a REAL tracking number, record');
md.push('> \`itemId,tracking,carrier\` in \`data/out/waybills.csv\` then run:');
md.push('>');
md.push('> \`\`\`\nnode scripts/apply-waybills.mjs --csv data/out/waybills.csv\n\`\`\`');
md.push('');

for (const [key, ch] of entries) {
  md.push(`## ${ch.originalName || key} — ${ch.channel} · ${ch.pendingCount} items · ${ch.supplierTotal} MAD`);
  md.push('');
  md.push(`Order refs: ${ch.orderRefs}`);
  md.push('');
  md.push('Items:');
  md.push(itemLines(ch.originalName));
  md.push('');
  md.push(channelBlock(ch));
  md.push('');
  md.push('---');
  md.push('');
}

writeFileSync(resolve(OUT, 'po-outreach-drafts.md'), md.join('\n'));
console.log(JSON.stringify({
  ok: true,
  suppliers: entries.length,
  file: resolve(OUT, 'po-outreach-drafts.md'),
  top: entries.slice(0, 3).map(([k, c]) => `${c.originalName} (${c.channel}, ${c.pendingCount} items, ${c.supplierTotal} MAD)`),
}, null, 2));